  'help.send': 'Jegy küldése',
  'help.ticketSent': 'Jegy elküldve!',
  'help.ticketSentDesc': 'Megkaptuk a kérésed. Csapatunk 24 órán belül válaszol emailben.',
  'help.close': 'Bezárás',
  'help.ticketError': 'Hiba a jegy küldésekor. Próbáld újra.',
  'help.type.cant_login': 'Nem tudok bejelentkezni',
  'help.type.email_issue': 'Email probléma',
  'help.type.security': 'Biztonság',
  'help.type.other': 'Egyéb',
  'help.faq.cantLogin.q': 'Nem tudok hozzáférni a fiókomhoz',
  'help.faq.cantLogin.a': 'Ellenőrizd, hogy a helyes emailt és jelszót használod-e. Ha elfelejtetted a jelszavad, kattints az "Elfelejtetted a jelszavad?" gombra a bejelentkező képernyőn. Ha a probléma továbbra is fennáll, hozz létre egy támogatási jegyet.',
  'help.faq.notReceiving.q': 'Nem kapok emailt',
  'help.faq.notReceiving.a': 'Először ellenőrizd a Spam mappát. Győződj meg róla, hogy a tárolód nem tele. Ha a probléma továbbra is fennáll, erősítsd meg, hogy a feladó helyes email címet használt, és hozz létre egy jegyet.',
  'help.faq.cantSend.q': 'Nem tudok emailt küldeni',
  'help.faq.cantSend.a': 'Ellenőrizd az internetkapcsolatodat és hogy a címzett email címe helyes-e. Nézd meg, hogy a csatolmányok nem haladják-e meg a 25MB-ot. Próbáld újra néhány perc múlva.',
  'help.faq.forgotPassword.q': 'Elfelejtettem a jelszavamat',
  'help.faq.forgotPassword.a': 'A bejelentkező képernyőn kattints az "Elfelejtetted a jelszavad?" gombra, és kövesd az utasításokat a jelszó visszaállításához a helyreállító emailen keresztül.',
  'help.faq.accountSecurity.q': 'Azt hiszem, a fiókomat feltörték',
  'help.faq.accountSecurity.a': 'Azonnal változtasd meg a jelszavad. Ellenőrizd a Kimenő mappát, hogy nem küldtél-e üzeneteket, amiket nem te küldtél. Aktiváld a kétlépcsős azonosítást a Beállítások > Biztonság menüben. Ha szükséges, hozz létre egy sürgős jegyet.',
  'help.faq.appAccess.q': 'Hogyan érem el az appot a mobilomon?',
  'help.faq.appAccess.a': 'A Chatyy-t elérheted a böngészőben a chatyy.com.br oldalon, vagy letöltheted az appunkat az eszközöd alkalmazásboltjából.',
  'privacy.title': 'Adatvédelmi Irányelvek',
  'privacy.subtitle': 'Hogyan védjük és kezeljük az adataidat',
  'privacy.lastUpdated': 'Utolsó frissítés: 2026 Március',
  'privacy.dataCollection.title': 'Adatgyűjtés',
  'privacy.dataCollection.body': 'Csak a szükséges információkat gyűjtjük az email szolgáltatáshoz: a neved, email címed és az elküldött és fogadott üzenetek tartalmát. Nem adjuk el és nem osztjuk meg a személyes adataidat harmadik felekkel marketing célokra.',
  'privacy.dataUsage.title': 'Hogyan használjuk az adataidat',
  'privacy.dataUsage.body': 'Az adataidat kizárólag az email szolgáltatás működtetésére és javítására használjuk, beleértve az üzenetek kézbesítését, spam szűrést, AI funkciókat (a beleegyezéseddel) és a fiók biztonságát.',
  'privacy.dataSecurity.title': 'Adatok Biztonsága',
  'privacy.dataSecurity.body': 'Ipari szabványú titkosítást (TLS/SSL) használunk az összes adat átvitelére és tárolására. A munkamenetek titkosított tokenekkel és CSRF védelemmel vannak védve. Rendszeresen auditáljuk a biztonsági gyakorlatainkat.',
  'privacy.cookies.title': 'Sütik és Helyi Tárolás',
  'privacy.cookies.body': 'Elengedhetetlen sütiket és helyi tárolást használunk a munkameneted fenntartására, a preferenciáid (téma, nyelv) megjegyzésére és a zökkenőmentes élmény biztosítására. Nem használunk harmadik féltől származó nyomkövető sütiket.',
  'privacy.thirdParties.title': 'Harmadik Fél Szolgáltatások',
  'privacy.thirdParties.body': 'Harmadik fél szolgáltatásokat használhatunk specifikus funkciókhoz, mint például AI (Anthropic Claude) és push értesítések. Ezek a szolgáltatások a saját adatvédelmi irányelveiket követik, és csak a minimális szükséges adatokat dolgozzák fel.',
  'privacy.rights.title': 'Jogai',
  'privacy.rights.body': 'Bármikor jogod van hozzáférni, módosítani, exportálni vagy törölni a személyes adataidat. Az adataidat a Beállításokban kezelheted, vagy kapcsolatba léphetsz a támogatásunkkal.',
  'privacy.contact.title': 'Lépj Velünk Kapcsolatba',
  'privacy.contact.body': 'Adatvédelmi kérdések vagy adatkérelmek esetén lépj kapcsolatba a privacy@chatyy.com.br címen. 30 napon belül válaszolunk.',
  'terms.title': 'Szolgáltatási Feltételek',
  'terms.subtitle': 'A Chatyy használati irányelvei',
  'terms.lastUpdated': 'Utolsó frissítés: 2026 Március',
  'terms.acceptance.title': 'A Feltételek Elfogadása',
  'terms.acceptance.body': 'A Chatyy használatával elfogadod ezeket a Szolgáltatási Feltételeket. Ha nem értesz egyet ezek bármely részével, ne használd a szolgáltatást.',
  'terms.services.title': 'A Szolgáltatások Leírása',
  'terms.services.body': 'A Chatyy email kommunikációs szolgáltatásokat nyújt, beleértve az email küldést, fogadást és kezelését, valamint AI funkciókat, naptár integrációt és videokonferenciát.',
  'terms.accounts.title': 'Felhasználói Fiókok',
  'terms.accounts.body': 'Te vagy felelős a hitelesítő adataid biztonságának megőrzéséért. Ne oszd meg a jelszavad, és ne engedj jogosulatlan hozzáférést a fiókodhoz. Legalább 13 évesnek kell lenned a szolgáltatás használatához.',
  'terms.conduct.title': 'Elfogadható Használat',
  'terms.conduct.body': 'Elfogadod, hogy nem használod a szolgáltatást spam, malware, phishing vagy bármilyen illegális tartalom küldésére. Ne próbáld meg hozzáférni más felhasználók fiókjaihoz, vagy megszakítani a szolgáltatás infrastruktúráját.',
  'terms.content.title': 'A Tartalom Tulajdonjoga',
  'terms.content.body': 'Te tartod a tulajdonjogot minden olyan tartalom felett, amit a szolgáltatáson keresztül létrehozol és küldesz. Nem igényeljük a tulajdonjogot az emailjeid vagy csatolmányaid felett. Feldolgozhatjuk a tartalmat, ahogy szükséges a szolgáltatás nyújtásához.',
  'terms.limitation.title': 'Felelősség Korlátozása',
  'terms.limitation.body': 'A Chatyy "ahogy van" alapon kerül biztosításra. 99,9%-os rendelkezésre állásra törekszünk, de nem garantáljuk a megszakítás nélküli szolgáltatást. Nem vállalunk felelősséget közvetett, véletlen vagy következményes károkért, amelyek a szolgáltatás használatából erednek.',
  'terms.termination.title': 'Fiók Lezárása',
  'terms.termination.body': 'Felfüggeszthetjük vagy lezárhatjuk azokat a fiókokat, amelyek megsértik ezeket a feltételeket. Bármikor törölheted a fiókodat a Beállításokban. A lezárás után az adataidat 30 napon belül töröljük.',
