  'plans.faqWhatIsPlus': 'Mi az a Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Ez a Chatyy prémium terve, amely védi az összes beszélgetésedet, fényképedet és videódat. A Chatyy One-nal, még ha véletlenül törölsz is valamit, 30 napon belül visszaállíthatod. Ezen kívül 200 GB tárolót kapsz, One AI-t mint személyes asszisztenst, és akár 100 MB-os fájlokat is küldhetsz.',
  'plans.faqCancelAnswer': 'A terved aktív marad a kifizetett időszak végéig. Ezután visszatérsz az ingyenes tervre. Azok a fényképek és videók, amelyek meghaladják a 15 GB-ot, további 30 napig elérhetők lesznek a letöltéshez.',
  'plans.faqHowFamily': 'Hogyan működik a Pro terv?',
  'plans.faqHowFamilyAnswer': 'Legfeljebb 4 családtagot adhatsz hozzá. Mindenki 500 GB tárolót oszt meg, és megkapja a Chatyy One összes előnyét. Mindenkinek van saját privát tere — senki sem látja a mások fájljait.',
  'plans.faqChangePlanAnswer': 'Igen! Ha a Plus-ról Pro-ra frissítesz, csak az arányos különbséget fogják felszámolni. Ha visszalépsz, a jelenlegi terv a periódus végéig érvényben marad.',
